/// <summary>
/// Form class for AVARUMWeightIn, handling weight-in operations for sales and purchase lines.
/// </summary>
[Form]
public class AVARUMWeightIn extends FormRun implements IFormDataSourceManager
{
    AVARUMWeightInParameters weightInParameters;
    AVARUMWeightInOriginId weightInOriginId;
    FormControlName onSearchCtrl;

}

/// <summary>
/// Initializes the form, disables saved views, and configures the form based on the menu item caller.
/// </summary>
public void init()
{
    weightInParameters = AVARUMWeightInParameters::find();

    super();

    this.disableSavedViewsOnForm();
    this.configureForm();
}

/// <summary>
/// Configures the form based on the menu item that called it.
/// Sets visibility of tab pages and executes queries as needed.
/// </summary>
private void configureForm()
{
    str menuItemCallerName;                           

    VendorOrderTabPage.visible(false);
    CustomerOrderTabPage.visible(false);

    menuItemCallerName = this.args().menuItemName();

    switch (menuItemCallerName)
    {
        case menuItemDisplayStr(AVARUMWeightInSales):
            weightInOriginId = AVARUMWeightInOrigin::Sales;
            if (this.args().record() && this.args().record().TableId==tableNum(WHSLoadTable))
            {
                this.addLoadFilter(this.args().record());
            }
            CustomerOrderTabPage.visible(true);
            SalesLine_ds.executeQuery();
            ContentHeaderText.text("@SYS37101");
            break;

        case menuItemDisplayStr(AVARUMWeightInPurch):
            weightInOriginId = AVARUMWeightInOrigin::Purch;
            if (this.args().record() && this.args().record().TableId==tableNum(WHSLoadTable))
            {
                this.addLoadFilter(this.args().record());
            }
            VendorOrderTabPage.visible(true);
            PurchLine_ds.executeQuery();
            ContentHeaderText.text("@SYS9283");
            break;

        default:
            Global::error("@AVARUM:InvalidMenuItemCaller");
            break;
    }                          

    /// Validate that WeightIn Scale Type is configured
    if (weightInParameters.ScaleType == AVARUMWeightInScaleType::None)
    {
        Global::warning("@AVARUM:WeightInScaleTypeNotConfigured");
    }           
}

/// <summary>
/// Adds an filter for loadId
/// </summary>
/// <param name = "_WHSLoadTable">LoadId</param>
private void addLoadFilter(WHSLoadTable _WHSLoadTable)
{
    if (weightInOriginId == AVARUMWeightInOrigin::Purch)
    {
        QueryBuildDataSource qbds=PurchLine_ds.query().dataSourceTable(tableNum(PurchLine));
        QueryBuildDataSource qbdsLoadLine=qbds.addDataSource(tableNum(WHSLoadLine));
        qbdsLoadLine.joinMode(JoinMode::ExistsJoin);
        qbdsLoadLine.addLink(fieldNum(PurchLine, InventTransId), fieldNum(WHSLoadLine, InventTransId));
        qbdsLoadLine.addRange(fieldNum(WHSLoadLine, LoadId)).value(queryValue(_WHSLoadTable.LoadId));
    }
    else if (weightInOriginId == AVARUMWeightInOrigin::Sales)
    {
        QueryBuildDataSource qbds=SalesLine_ds.query().dataSourceTable(tableNum(SalesLine));
        QueryBuildDataSource qbdsLoadLine=qbds.addDataSource(tableNum(WHSLoadLine));
        qbdsLoadLine.joinMode(JoinMode::ExistsJoin);
        qbdsLoadLine.addLink(fieldNum(SalesLine, InventTransId), fieldNum(WHSLoadLine, InventTransId));
        qbdsLoadLine.addRange(fieldNum(WHSLoadLine, LoadId)).value(queryValue(_WHSLoadTable.LoadId));
    }
}

/// <summary>
/// Runs the form and enables the WeightInTabPage if a record is selected.
/// </summary>
public void run()
{
    super();

    WeightInTabPage.enabled(this.isRecordSelected());
}

/// <summary>
/// Checks if any record is selected in the appropriate data source based on the origin type.
/// </summary>
/// <returns>True if a record is selected; otherwise, false.</returns>
private boolean isRecordSelected()
{
    boolean selected;

    switch (weightInOriginId)
    {
        case AVARUMWeightInOrigin::Sales:
            selected = SalesLine_ds.cursor().RecId != 0;
            break;

        case AVARUMWeightInOrigin::Purch:
            selected = PurchLine_ds.cursor().RecId != 0;
            break;
    }

    /// Validate that WeightIn Scale Type is configured
    if (weightInParameters.ScaleType == AVARUMWeightInScaleType::None)
    {
        selected = false;
    }

    return selected;
}

/// <summary>
/// Applies filter to the query based on the selected origin and the state of the SecondWeightingOpenCb checkbox.
/// </summary>
private void applyFilter()
{
    Query queryOrigin;
    QueryBuildDataSource qbdsOrigin;
    QueryBuildDataSource qbdsMWeightInHistory1;
    QueryBuildDataSource qbdsMWeightInHistory2;
    FieldId originRecIdFieldId;
    FieldId originDocumentIdFieldId;

    switch (weightInOriginId)
    {
        case AVARUMWeightInOrigin::Sales:
            queryOrigin = SalesLine_ds.query();
            qbdsOrigin = SalesLine_ds.query().dataSourceTable(tableNum(SalesLine));
            originRecIdFieldId = fieldNum(SalesLine, RecId);
            originDocumentIdFieldId = fieldNum(SalesLine, SalesId);
            break;

        case AVARUMWeightInOrigin::Purch:
            queryOrigin = PurchLine_ds.query();
            qbdsOrigin = PurchLine_ds.query().dataSourceTable(tableNum(PurchLine));
            originRecIdFieldId = fieldNum(PurchLine, RecId);
            originDocumentIdFieldId = fieldNum(PurchLine, PurchId);
            break;
    }

    qbdsOrigin.clearRange(originDocumentIdFieldId);

    if (DocumentIdSearch.text())
    {
        qbdsOrigin.addRange(originDocumentIdFieldId).value(Global::queryValue(DocumentIdSearch.text()));
    }

    qbdsMWeightInHistory1 = queryOrigin.dataSourceTable(tableNum(AVARUMWeightInHistory), 1);
    qbdsMWeightInHistory2 = queryOrigin.dataSourceTable(tableNum(AVARUMWeightInHistory), 2);

    if (qbdsMWeightInHistory1)
    {
        qbdsMWeightInHistory1.enabled(false);
    }

    if (qbdsMWeightInHistory2)
    {
        qbdsMWeightInHistory2.enabled(false);
    }

    if (SecondWeightingOpenCb.checked())
    {
        if (!qbdsMWeightInHistory1)
        {
            qbdsMWeightInHistory1 = qbdsOrigin.addDataSource(tablenum(AVARUMWeightInHistory), strFmt('%1_1', Global::tableId2Name(tableNum(AVARUMWeightInHistory))));
            qbdsMWeightInHistory1.relations(false);
            qbdsMWeightInHistory1.joinMode(JoinMode::ExistsJoin);
            qbdsMWeightInHistory1.addLink(originRecIdFieldId, fieldNum(AVARUMWeightInHistory, OriginRefRecId));                               
            qbdsMWeightInHistory1.addRange(fieldNum(AVARUMWeightInHistory, Step)).value(Global::queryValue(AVARUMWeightInStep::First));
            qbdsMWeightInHistory1.addRange(fieldNum(AVARUMWeightInHistory, OriginId)).value(Global::queryValue(weightInOriginId));
            qbdsMWeightInHistory1.addRange(fieldNum(AVARUMWeightInHistory, OriginRefTableId)).value(Global::queryValue(qbdsOrigin.table()));
        }

        if (!qbdsMWeightInHistory2)
        {
            qbdsMWeightInHistory2 = qbdsOrigin.addDataSource(tablenum(AVARUMWeightInHistory), strFmt('%1_2', Global::tableId2Name(tableNum(AVARUMWeightInHistory))));
            qbdsMWeightInHistory2.relations(false);
            qbdsMWeightInHistory2.joinMode(JoinMode::NoExistsJoin);
            qbdsMWeightInHistory2.addLink(originRecIdFieldId, fieldNum(AVARUMWeightInHistory, OriginRefRecId));                                 
            qbdsMWeightInHistory2.addRange(fieldNum(AVARUMWeightInHistory, Step)).value(Global::queryValue(AVARUMWeightInStep::Second));
            qbdsMWeightInHistory2.addRange(fieldNum(AVARUMWeightInHistory, OriginId)).value(Global::queryValue(weightInOriginId));
            qbdsMWeightInHistory2.addRange(fieldNum(AVARUMWeightInHistory, OriginRefTableId)).value(Global::queryValue(qbdsOrigin.table()));
        }

        qbdsMWeightInHistory1.enabled(true);
        qbdsMWeightInHistory2.enabled(true);
    }
}

/// <summary>
/// Sets the record for the specified data source name.
/// </summary>
/// <param name = "_dataSourceName">The name of the data source.</param>
/// <param name = "_record">The record to set.</param>
public void setRecord(DataSourceName _dataSourceName, Common _record)
{
    try
    {
        FormObjectSet fos = this.dataSource(_dataSourceName);
        fos.positionToRecord(_record);
    }
    catch
    {
        Global::exceptionTextFallThrough();
    }
}

/// <summary>
/// Handles task events for the form, particularly the Enter key to execute queries based on the origin type.
/// </summary>
/// <param name = "_p1">The task ID.</param>
/// <returns>The result of the task processing.</returns>
public int task(int _p1)
{
    #Task
    #define.taskF2(4658)

    int ret;

    ret = super(_p1);

    /// Handle Enter key to execute queries based on origin type if onSearch is true
    if (onSearchCtrl == DocumentIdSearch.name() && _p1 == #taskEnter)
    {
        switch (weightInOriginId)
        {
            case AVARUMWeightInOrigin::Sales:
                SalesLine_ds.executeQuery();
                break;

            case AVARUMWeightInOrigin::Purch:
                PurchLine_ds.executeQuery();
                break;
        }
    }
    else if (_p1 == #taskF2)
    {
        AVARUMWeightInHistory_Value.allowEdit(false);

        /// If the current step is not 'Amount' editing is allowed. 
        /// Reread the data source and reset status and message
        if (AVARUMWeightInHistory.Step != AVARUMWeightInStep::Amount)
        {
            AVARUMWeightInHistory_Value.allowEdit(true);
            AVARUMWeightInHistory_ds.reread();
            AVARUMWeightInHistory.StatusId = AVARUMWeightInStatus::OK;
            AVARUMWeightInHistory.Message = '';
            AVARUMWeightInHistory.IsMaintainedManuallyId = NoYes::Yes;
            AVARUMWeightInHistory.write();
            AVARUMWeightInHistory_ds.research(true);
        }
    }

    return ret;
}

/// <summary>
/// Activates a timer to periodically update the form based on weight-in history processing status.
/// </summary>
private void activateTimer()
{
    element.setTimeoutEx(formMethodStr(AVARUMWeightIn, updateForm), conNull(), weightInParameters.UpdateInterval);
}

/// <summary>
/// Updates the form by re-executing the AVARUMWeightInHistory_ds query and reactivating the timer if processing is not complete.
/// </summary>
/// <param name = "_result">The result of the asynchronous task.</param>
private void updateForm(AsyncTaskResult _result)
{
    if (!element.closed()) //otherwise will be executed even after form close.
    {   
        boolean isTimeerRequired;

        AVARUMWeightInHistory_ds.executeQuery(); 
        isTimeerRequired = !AVARUMWeightInHistory.isProcessed();
        this.updateButtonActions();

        if (isTimeerRequired)
        {
            element.activateTimer();
        }               
    }
}

/// <summary>
/// Update actions buttons AVARUMWMSJournalReceptionWeighing
/// </summary>
protected void updateButtonActions()
{
    AVARUMWeightInHistory locAVARUMWeightInHistory;
    if (PurchLine)
    {
        select firstonly RecId from locAVARUMWeightInHistory
        where locAVARUMWeightInHistory.OriginId==weightInOriginId
           && locAVARUMWeightInHistory.OriginRefRecId==PurchLine.RecId
           && locAVARUMWeightInHistory.Step==AVARUMWeightInStep::Amount;
    }
    AVARUMWMSJournalReceptionWeighing.enabled((locAVARUMWeightInHistory.recid!=0));

    if (SalesLine)
    {
        select firstonly RecId from locAVARUMWeightInHistory
        where locAVARUMWeightInHistory.OriginId==weightInOriginId
           && locAVARUMWeightInHistory.OriginRefRecId==SalesLine.RecId
           && locAVARUMWeightInHistory.Step==AVARUMWeightInStep::Amount;
    }
    AVARUMCheckAndReserve.enabled((locAVARUMWeightInHistory.recid!=0));
}

/// <summary>
/// Validates if the weight-in record is valid.
/// </summary>
/// <returns>True if valid; otherwise, false.</returns>
private boolean isWeightInValid()
{
    boolean ret;
    ret = true;

    if (AVARUMWeightInHistory_ds.cursor() && 
       !AVARUMWeightInHistory.validateField(fieldNum(AVARUMWeightInHistory, Identifier)))
    {
        ret = false;
    }

    return ret;
}

/// <summary>
/// Handles selection changes in the form.
/// Enables WeightInTabPage and executes AVARUMWeightInHistory_ds query.
/// </summary>
public void selectionChanged()
{
    super();

    WeightInTabPage.enabled(element.isRecordSelected());
    AVARUMWeightInHistory_ds.executeQuery();
}

/// <summary>
/// Initializes the SalesLine data source, adds ranges and joins to InventTable.
/// </summary>
public void init()
{
    QueryBuildDataSource qbdsSalesLine;
    QueryBuildDataSource queryBuildDataSourceInventTable;

    super();

    qbdsSalesLine = this.query().dataSourceTable(tableNum(SalesLine));
    qbdsSalesLine.addRange(fieldNum(SalesLine, RemainSalesPhysical)).value(Global::queryValue('>0'));
    qbdsSalesLine.addRange(fieldNum(SalesLine, SalesType)).value(Global::queryValue(SalesType::Sales));
    qbdsSalesLine.addSortField(fieldNum(SalesLine, ShippingDateConfirmed), SortOrder::Descending);

    queryBuildDataSourceInventTable = qbdsSalesLine.addDataSource(tablenum(InventTable));
    queryBuildDataSourceInventTable.addRange(fieldNum(InventTable, AVARUMWeighSales)).value(Global::queryValue(NoYes::Yes));
    queryBuildDataSourceInventTable.relations(true);
    queryBuildDataSourceInventTable.joinMode(JoinMode::ExistsJoin);
}

/// <summary>
/// Executes the SalesLine query, applies ranges and filter, and calls super.
/// </summary>
public void executeQuery()
{
    element.applyFilter();

    super();
}

/// <summary>
/// Handles the active state of the SalesLine data source
/// </summary>
/// <returns>1 if active; otherwise, 0.</returns>
public int active()
{
    int ret;

    ret = super();

    WeightInButton.enabled(true);

    return ret;
}

/// <summary>
/// Handles selection changes in the form.
/// Enables WeightInTabPage and executes AVARUMWeightInHistory_ds query.
/// </summary>
public void selectionChanged()
{
    super();

    WeightInTabPage.enabled(element.isRecordSelected());
    AVARUMWeightInHistory_ds.executeQuery();
}

/// <summary>
/// Initializes the PurchLine data source, adds ranges and joins to InventTable.
/// </summary>
public void init()
{
    QueryBuildDataSource qbdsPurchLine;
    QueryBuildDataSource queryBuildDataSourceInventTable;

    super();

    qbdsPurchLine = this.query().dataSourceTable(tableNum(PurchLine));
    qbdsPurchLine.addRange(fieldNum(PurchLine, RemainPurchPhysical)).value(Global::queryValue('>0'));
    qbdsPurchLine.addRange(fieldNum(PurchLine, PurchaseType)).value(Global::queryValue(PurchaseType::Purch));
    qbdsPurchLine.addSortField(fieldNum(PurchLine, ConfirmedDlv), SortOrder::Descending);

    queryBuildDataSourceInventTable = qbdsPurchLine.addDataSource(tablenum(InventTable));
    queryBuildDataSourceInventTable.addRange(fieldNum(InventTable, AVARUMWeighBlanket)).value(Global::queryValue(NoYes::Yes));
    queryBuildDataSourceInventTable.relations(true);
    queryBuildDataSourceInventTable.joinMode(JoinMode::ExistsJoin);
}

/// <summary>
/// Executes the PurchLine query, applies ranges, and calls super.
/// </summary>
public void executeQuery()
{
    element.applyFilter();

    super();
}

/// <summary>
/// Handles the active state of the PurchLine data source
/// </summary>
/// <returns>1 if active; otherwise, 0.</returns>
public int active()
{
    int ret;

    ret = super();

    WeightInButton.enabled(true);
    element.updateButtonActions();

    return ret;
}

/// <summary>
/// Initializes the AVARUMWeightInHistory data source, clears ranges, and adds sort fields.
/// </summary>
public void init()
{
    QueryBuildDataSource qbdsMWeightInHistory;

    super();

    qbdsMWeightInHistory = this.query().dataSourceTable(tableNum(AVARUMWeightInHistory));
    qbdsMWeightInHistory.clearRanges();

    switch (weightInOriginId)
    {
        case AVARUMWeightInOrigin::Sales:
        case AVARUMWeightInOrigin::Purch:
            qbdsMWeightInHistory.addRange(fieldNum(AVARUMWeightInHistory, OriginId));
            qbdsMWeightInHistory.addRange(fieldNum(AVARUMWeightInHistory, OriginRefRecId));
            break;
    }

    qbdsMWeightInHistory.addSortField(fieldNum(AVARUMWeightInHistory, Step), SortOrder::Descending);
}

/// <summary>
/// Executes the AVARUMWeightInHistory query, applies ranges based on origin, and calls super.
/// </summary>
public void executeQuery()
{
    QueryBuildDataSource qbdsMWeightInHistory;
    AVARUMWeightInOrigin origin;
    RefRecId originRefRecId;

    qbdsMWeightInHistory = this.query().dataSourceTable(tableNum(AVARUMWeightInHistory));

    switch (weightInOriginId)
    {
        case AVARUMWeightInOrigin::Sales:
            origin = AVARUMWeightInOrigin::Sales;
            originRefRecId = SalesLine_ds.cursor().RecId;
            break;

        case AVARUMWeightInOrigin::Purch:
            origin = AVARUMWeightInOrigin::Purch;
            originRefRecId = PurchLine_ds.cursor().RecId;
            break;
    }

    qbdsMWeightInHistory.rangeField(fieldNum(AVARUMWeightInHistory, OriginId)).value(Global::queryValue(Global::enum2int(origin)));
    qbdsMWeightInHistory.rangeField(fieldNum(AVARUMWeightInHistory, OriginRefRecId)).value(Global::queryValue(originRefRecId));

    super();
}

/// <summary>
/// Determines if the Re-Weight In button should be active and allows editing of the identifier.
/// </summary>
/// <returns>1 if active; otherwise, 0.</returns>
public int active()
{
    int ret;
    boolean isWeightInDone;
    AVARUMWeightInHistory weightInHistory;

    ret = super();

    weightInHistory = this.cursor();
    isWeightInDone =  weightInHistory.Step != AVARUMWeightInStep::First || AVARUMWeightInHistory::isDone(weightInHistory.OriginId, weightInHistory.OriginRefTableId, weightInHistory.OriginRefRecId);
    AVARUMWeightInHistory_ReWeightIn.visible(!isWeightInDone);
    AVARUMWeightInHistory_Identifier.allowEdit(!isWeightInDone);                     
    WeightInPrint.enabled(weightInHistory.Step == AVARUMWeightInStep::Amount);
    WeightInDelete.enabled(weightInHistory.Step != AVARUMWeightInStep::Amount);
    WeightInButton.enabled(weightInHistory.isProcessed() && !isWeightInDone);
    WeightInMove.enabled(weightInHistory.isProcessed());
    AVARUMWeightInHistory_ds.allowEdit(weightInHistory.isProcessed());

    return ret;
}

