{
    SalesLine_ds.executeQuery();
    SalesLine_ds.active();
}

/// <summary>
/// Test XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX
/// </summary>
public void clicked()
{
    super();
    AVARUMWeightInHistory locAVARUMWeightInHistory;
    select firstonly locAVARUMWeightInHistory
        where locAVARUMWeightInHistory.OriginRefTableId==SalesLine.TableId
            && locAVARUMWeightInHistory.OriginRefRecId==SalesLine.RecId
            && locAVARUMWeightInHistory.Step==AVARUMWeightInStep::Amount;
    if (!locAVARUMWeightInHistory)
    {
        throw error("@AVARUM:AVARUMWMSJournalTableMsg1");
    }
    AVARUMWeightProcessManager::processOutgoing(this, locAVARUMWeightInHistory);

}

