    PurchLine_ds.active();
}

/// <summary>
/// Call and create Item arrival journal (WMSJOurnalTable)
/// </summary>
public void clicked()
{                        
    //super();
    AVARUMWeightInHistory locAVARUMWeightInHistory;
    select firstonly locAVARUMWeightInHistory
        where locAVARUMWeightInHistory.OriginRefTableId==PurchLine.TableId
            && locAVARUMWeightInHistory.OriginRefRecId==PurchLine.RecId
            && locAVARUMWeightInHistory.Step==AVARUMWeightInStep::Amount;
    if (!locAVARUMWeightInHistory)
    {
        throw error("@AVARUM:AVARUMWMSJournalTableMsg1");
    }             
    AVARUMWeightProcessManager::createAndOpenReceiptJournal(this, locAVARUMWeightInHistory);
}

/// <summary>
/// Handles the click event for the Weight In button.
/// Runs the menu function and refreshes AVARUMWeightInHistory_ds.
/// </summary>
public void clicked()
{
    MenuFunction menuFunction;
    Args args;

    if (element.isWeightInValid())
    {
        if (AVARUMWeightInHistory_ds.cursor())
        {
            AVARUMWeightInHistory_ds.write();
        }

        menuFunction = new MenuFunction(this.menuItemName(), this.menuItemType());
        args = new Args(element);
        args.menuItemName(this.menuItemName());
        args.menuItemType(this.menuItemType());

        switch (this.menuItemName())
        {
            case menuItemActionStr(AVARUMWeightIn):
                switch (weightInOriginId)
                {
                    case AVARUMWeightInOrigin::Sales:
                        args.record(SalesLine_ds.cursor());
                        break;

                    case AVARUMWeightInOrigin::Purch:
                        args.record(PurchLine_ds.cursor());
                        break;
                }
                break;

            case menuItemActionStr(AVARUMWeightInRepeat):
                args.record(AVARUMWeightInHistory_ds.cursor());
                break;
        }

        // super();
        menuFunction.run(args);

        AVARUMWeightInHistory_ds.allowEdit(false);
        AVARUMWeightInHistory_ds.executeQuery();

        element.activateTimer();
    }
}

