/// <summary>
/// Handles the click event for the Weight In Delete button.
/// </summary>
public void clicked()
{
    AVARUMWeightInHistory.skipDataSourceValidateDelete(true);
    AVARUMWeightInManager::deleteWeightInHistory(AVARUMWeightInHistory_ds.cursor());                                             
    AVARUMWeightInHistory.skipDataSourceValidateDelete(false);
    AVARUMWeightInHistory_ds.executeQuery();
    AVARUMWeightInHistory_ds.active();
}

