/// <summary>
/// Handles modifications to the control.
/// </summary>
/// <returns>True if modified; otherwise, false.</returns>
public boolean modified()
{
    boolean ret;
    AVARUMWeightInHistory weightInHistory;
    AVARUMWeightInValue value;

    ret = super();

    weightInHistory = AVARUMWeightInHistory_ds.cursor();
    value = weightInHistory.Value;
    AVARUMWeightInHistory_ds.cursor().reread();
    weightInHistory.Value = value;

    AVARUMWeightInHistory_Value.allowEdit(false);
    AVARUMWeightInManager::createOrUpdateWeightInAmount(AVARUMWeightInHistory_ds.cursor());
    AVARUMWeightInHistory_ds.executeQuery();

    return ret;
}

