    // super();
    menuFunction.run(args);

    AVARUMWeightInHistory_ds.executeQuery();
    element.activateTimer();
}

/// <summary>
/// Handles the click event for the OK button.
/// </summary>
public void clicked()
{   
    if (!element.isWeightInValid())
    {
        throw Global::warning("@AVARUM:FixDataBeforeProceeding");
    }

    super();
}
